/*
 * One Piece Guesser: game logic and interface.
 *
 * Data comes from characters.js (window.CHARACTERS, window.ARCS), generated by
 * tools/build_data.py. The column rules follow PLAN.md "Column rules".
 * The logic section has no DOM access, so tools/selfcheck.js can run it in Node.
 */
(function (global) {
  "use strict";

  // ---------------------------------------------------------------------------
  // Comparison results

  const MATCH = "match";     // green
  const PARTIAL = "partial"; // yellow
  const MISS = "miss";       // red
  const UNKNOWN = "unknown"; // gray: one side has no data

  // Races that count as related variants (yellow). PLAN.md "Race mapping".
  const RACE_FAMILIES = [
    ["Human", "Modified Human"],
    ["Giant", "Ancient Giant"],
    ["Skypiean", "Shandia", "Birkan"],
  ];

  // Words ignored when checking whether an affiliation names a character,
  // so "Whitebeard Pirates" -> "whitebeard" and "Kid Pirates" -> "kid".
  const GENERIC_WORDS = new Set([
    "pirates", "pirate", "family", "crew", "fleet", "grand", "army", "kingdom", "tribe",
    "gang", "band", "group", "corps", "division", "squad", "unit", "club", "clan",
    "alliance", "company", "workers", "staff", "guards", "brothers", "household",
    "ally", "allies", "of", "the", "subordinates", "members",
  ]);

  // Titles that are not names on their own ("God" Usopp is not God's Army).
  const TITLE_WORDS = new Set([
    "god", "king", "queen", "prince", "princess", "captain", "doctor", "boss", "master",
    "lord", "lady", "sir", "saint", "miss", "mister", "big", "the", "of",
  ]);

  const HINT_THRESHOLDS = { fruit: 3, occupation: 5, affiliation: 7 };

  const isMissing = (v) => v === null || v === undefined || (Array.isArray(v) && v.length === 0);
  const sameSet = (a, b) => a.length === b.length && a.every((x) => b.includes(x));
  const norm = (s) => String(s).toLowerCase().trim();

  /** One side unknown -> gray; both unknown -> green; otherwise null (compare normally). */
  function unknownRule(g, s) {
    const gMissing = isMissing(g);
    const sMissing = isMissing(s);
    if (gMissing && sMissing) return { state: MATCH };
    if (gMissing || sMissing) return { state: UNKNOWN };
    return null;
  }

  function compareExact(g, s) {
    return unknownRule(g, s) || { state: g === s ? MATCH : MISS };
  }

  /** Numbers: green if equal, otherwise red with an arrow pointing toward the secret. */
  function compareNumber(g, s) {
    const unknown = unknownRule(g, s);
    if (unknown) return unknown;
    if (g === s) return { state: MATCH };
    return { state: MISS, arrow: s > g ? "up" : "down" };
  }

  function raceFamily(race) {
    const index = RACE_FAMILIES.findIndex((family) => family.includes(race));
    return index === -1 ? race : "family " + index;
  }

  /** Same races green; sharing one race, or related variants, yellow. */
  function compareRace(g, s) {
    const unknown = unknownRule(g, s);
    if (unknown) return unknown;
    if (sameSet(g, s)) return { state: MATCH };
    const sFamilies = s.map(raceFamily);
    if (g.some((r) => s.includes(r)) || g.map(raceFamily).some((f) => sFamilies.includes(f))) {
      return { state: PARTIAL };
    }
    return { state: MISS };
  }

  // --- Affiliation

  function affiliationCore(name) {
    return norm(name)
      .replace(/'s(?=\s|$)/g, "") // "Tom's Workers" -> "tom workers", but keep "Who's-Who"
      .split(/\s+/)
      .filter((w) => w && !GENERIC_WORDS.has(w) && !/^\d+(st|nd|rd|th)$/.test(w))
      .join(" ");
  }

  const keyCache = new Map();

  /** Names an affiliation could use for a character: name, name parts, epithets. */
  function nameKeys(c) {
    if (keyCache.has(c.id)) return keyCache.get(c.id);
    const keys = new Set();
    const tokens = norm(c.name).split(/\s+/).filter((t) => /^[a-z][a-z'\-]{2,}$/.test(t));
    keys.add(norm(c.name));
    tokens.forEach((t) => keys.add(t));
    for (const epithet of c.epithets || []) {
      keys.add(norm(epithet));
      // "Straw Hat Luffy" -> "straw hat" (only if at least two words are left)
      const withoutName = norm(epithet).split(/\s+/).filter((w) => !tokens.includes(w));
      if (withoutName.length >= 2) keys.add(withoutName.join(" "));
    }
    TITLE_WORDS.forEach((w) => keys.delete(w));
    keyCache.set(c.id, keys);
    return keys;
  }

  /** True if one of a's affiliations directly names character b. */
  function affiliationNames(a, b) {
    const keys = nameKeys(b);
    return (a.affiliations || []).some((aff) => {
      const core = affiliationCore(aff.name);
      return core.length >= 3 && keys.has(core);
    });
  }

  /**
   * Green: same current main group. Yellow: the guess's current group is one of
   * the secret's former groups, or one character's affiliation names the other.
   * Sharing a secondary group does not count.
   */
  function compareAffiliation(gc, sc) {
    const unknown = unknownRule(gc.affiliation, sc.affiliation);
    if (unknown) return unknown;
    if (norm(gc.affiliation) === norm(sc.affiliation)) return { state: MATCH };
    const secretFormer = (sc.affiliations || []).filter((a) => a.former).map((a) => norm(a.name));
    if (secretFormer.includes(norm(gc.affiliation))) return { state: PARTIAL };
    if (affiliationNames(gc, sc) || affiliationNames(sc, gc)) return { state: PARTIAL };
    return { state: MISS };
  }

  // --- Devil Fruit

  function fruitTypes(c) {
    return [...new Set((c.fruits || []).map((f) => f.type))];
  }

  /**
   * Green: same type(s), or neither has a fruit. Yellow: both have a fruit but of
   * different types (a failed SMILE is its own type). Red: only one has a fruit.
   */
  function compareFruit(gc, sc) {
    const g = fruitTypes(gc);
    const s = fruitTypes(sc);
    if (!g.length && !s.length) return { state: MATCH };
    if (!g.length || !s.length) return { state: MISS };
    if (g.includes(null) || s.includes(null)) {
      return { state: sameSet(g, s) ? MATCH : UNKNOWN }; // a fruit of unknown type
    }
    return { state: sameSet(g, s) ? MATCH : PARTIAL };
  }

  // --- Haki

  /** Green: same combination (none vs none too). Yellow: both have some. Red: only one has any. */
  function compareHaki(g, s) {
    if (!g.length && !s.length) return { state: MATCH };
    if (!g.length || !s.length) return { state: MISS };
    return { state: sameSet(g, s) ? MATCH : PARTIAL };
  }

  // --- Fighting style

  /** Green: same main style (None vs None too). Yellow: same family (Sword vs Dagger). */
  function compareStyle(gc, sc) {
    const unknown = unknownRule(gc.style, sc.style);
    if (unknown) return unknown;
    if (gc.style === sc.style) return { state: MATCH };
    return { state: gc.styleFamily === sc.styleFamily ? PARTIAL : MISS };
  }

  // --- First appearance

  /**
   * Green: same arc (or, for cover-page debuts, the same cover story).
   * Yellow: at least one debuted on a cover page, and both debuts fall in the same
   * arc (e.g. Garp on a cover during Arlong Park vs Arlong). Otherwise red with an
   * arrow by chapter.
   */
  function compareDebut(gc, sc) {
    if ((gc.coverStory || gc.arc) === (sc.coverStory || sc.arc)) return { state: MATCH };
    if ((gc.coverStory || sc.coverStory) && gc.arc === sc.arc) return { state: PARTIAL };
    return { state: MISS, arrow: sc.chapter > gc.chapter ? "up" : "down" };
  }

  // ---------------------------------------------------------------------------
  // Display helpers

  function formatBounty(b) {
    if (b === null || b === undefined) return "?";
    if (b === 0) return "None";
    const trim = (n, digits) => String(Number(n.toFixed(digits)));
    if (b >= 1e9) return "฿" + trim(b / 1e9, 3) + "B";
    if (b >= 1e6) return "฿" + trim(b / 1e6, 1) + "M";
    return "฿" + b.toLocaleString("en-US");
  }

  function formatFruit(c) {
    const types = fruitTypes(c);
    if (!types.length) return "None";
    return types.map((t) => t || "Unknown type").join(" / ");
  }

  /** "Arabasta Arc" -> "Arabasta"; cover stories keep their full title. */
  function formatArc(arc) {
    if (!arc) return "?";
    const mainArcs = (global.ARCS || []).map((a) => a.name);
    return mainArcs.includes(arc) ? arc.replace(/ Arc$/, "") : arc;
  }

  const show = (v, suffix = "") => (isMissing(v) ? "?" : v + suffix);

  // ---------------------------------------------------------------------------
  // Columns (order = order on screen)

  const COLUMNS = [
    { key: "gender", label: "Gender",
      text: (c) => show(c.gender),
      compare: (g, s) => compareExact(g.gender, s.gender) },
    { key: "race", label: "Race",
      text: (c) => (c.race.length ? c.race.join(" / ") : "?"),
      compare: (g, s) => compareRace(g.race, s.race) },
    { key: "affiliation", label: "Affiliation",
      text: (c) => show(c.affiliation),
      compare: compareAffiliation },
    { key: "status", label: "Status",
      text: (c) => show(c.status),
      compare: (g, s) => compareExact(g.status, s.status) },
    { key: "fruit", label: "Devil Fruit",
      text: formatFruit,
      compare: compareFruit },
    { key: "haki", label: "Haki",
      text: (c) => (c.haki.length ? c.haki.join(", ") : "None"),
      compare: (g, s) => compareHaki(g.haki, s.haki) },
    { key: "style", label: "Fighting Style",
      text: (c) => show(c.style),
      compare: compareStyle },
    { key: "bounty", label: "Bounty",
      text: (c) => formatBounty(c.bounty),
      compare: (g, s) => compareNumber(g.bounty, s.bounty) },
    { key: "height", label: "Height",
      text: (c) => show(c.height, " cm"),
      compare: (g, s) => compareNumber(g.height, s.height) },
    { key: "age", label: "Age",
      text: (c) => (isMissing(c.age) ? "?" : (c.ageApprox ? "~" : "") + c.age),
      compare: (g, s) => compareNumber(g.age, s.age) },
    { key: "debut", label: "First Appearance",
      text: (c) => c.coverStory || formatArc(c.arc),
      compare: compareDebut },
    { key: "episode", label: "Anime Ep.",
      text: (c) => show(c.episode),
      compare: (g, s) => compareNumber(g.episode, s.episode) },
    { key: "origin", label: "Origin",
      text: (c) => show(c.origin),
      compare: (g, s) => compareExact(g.origin, s.origin) },
  ];

  /** Compare a guessed character with the secret: one result per column. */
  function compareCharacters(guess, secret) {
    return COLUMNS.map((col) => ({ key: col.key, text: col.text(guess), ...col.compare(guess, secret) }));
  }

  // ---------------------------------------------------------------------------
  // Hints

  const HINTS = [
    { key: "fruit", label: "Fruit type", after: HINT_THRESHOLDS.fruit,
      text: (c) => (fruitTypes(c).length ? formatFruit(c) : "No Devil Fruit") },
    { key: "occupation", label: "Occupation", after: HINT_THRESHOLDS.occupation,
      text: (c) => (c.occupations && c.occupations.length ? c.occupations.slice(0, 2).join(", ") : "Unknown") },
    { key: "affiliation", label: "Affiliation", after: HINT_THRESHOLDS.affiliation,
      text: (c) => c.affiliation || "Unknown" },
  ];

  // ---------------------------------------------------------------------------
  // Self-check: guessing the secret itself must turn every column green.

  function selfCheck(characters) {
    const failures = [];
    for (const c of characters) {
      for (const result of compareCharacters(c, c)) {
        if (result.state !== MATCH) failures.push(`${c.name}: ${result.key} is ${result.state}`);
      }
    }
    return { checked: characters.length, failures };
  }

  // ---------------------------------------------------------------------------
  // Search: names, epithets ("Fire Fist") and aliases ("Kaido" for Kaidou)

  // "Who's-Who" -> "whos who", "Señor" -> "senor"
  const fold = (s) => String(s).normalize("NFD").replace(/[̀-ͯ]/g, "")
    .toLowerCase().replace(/['’]/g, "").replace(/[^a-z0-9]+/g, " ").trim();

  function buildSearchIndex(characters) {
    return characters.map((c) => ({
      c,
      name: fold(c.name),
      others: [...(c.epithets || []), ...(c.aliases || [])].map((t) => ({ raw: t, folded: fold(t) })),
    }));
  }

  /** How well a folded name matches the query: whole name > whole words > start > anywhere. */
  function matchScore(text, q) {
    if (text === q) return 4;
    if ((" " + text + " ").includes(" " + q + " ")) return 3; // "kuma" in "bartholomew kuma"
    if (text.startsWith(q) || text.split(" ").some((w) => w.startsWith(q))) return 2;
    if (text.includes(q)) return 1;
    return 0;
  }

  /**
   * Best matches first; ties go to the more famous character. The real name beats
   * an alias or epithet at the same match quality.
   */
  function searchCharacters(index, query, excludeIds = new Set(), limit = 8) {
    const q = fold(query);
    if (!q) return [];
    const found = [];
    for (const entry of index) {
      if (excludeIds.has(entry.c.id)) continue;
      let score = matchScore(entry.name, q) * 2 + 1;
      let via = null;
      for (const other of entry.others) {
        const aliasScore = matchScore(other.folded, q) * 2;
        if (aliasScore > score) { score = aliasScore; via = other.raw; }
      }
      if (score > 1) found.push({ c: entry.c, score, via });
    }
    found.sort((a, b) => b.score - a.score || b.c.fame - a.c.fame);
    return found.slice(0, limit);
  }

  function initials(name) {
    const words = name.replace(/\(.*?\)/g, "").split(/\s+/).filter((w) => /[A-Za-z]/.test(w));
    if (!words.length) return "?";
    const letters = words.length > 1 ? words[0][0] + words[words.length - 1][0] : words[0].slice(0, 2);
    return letters.toUpperCase();
  }

  function badgeColor(name) {
    let hue = 0;
    for (const ch of name) hue = (hue * 31 + ch.charCodeAt(0)) % 360;
    return `hsl(${hue} 52% 40%)`;
  }

  const wikiUrl = (c) => "https://onepiece.fandom.com/wiki/" + encodeURIComponent(c.name.replace(/ /g, "_"));

  const logic = {
    MATCH, PARTIAL, MISS, UNKNOWN, COLUMNS, HINTS, RACE_FAMILIES,
    compareCharacters, compareRace, compareAffiliation, compareFruit, compareHaki,
    compareNumber, compareExact, compareDebut, compareStyle, affiliationNames, formatBounty, selfCheck,
    buildSearchIndex, searchCharacters, initials,
  };
  global.OPG = logic;
  if (typeof module !== "undefined" && module.exports) module.exports = logic;

  // ---------------------------------------------------------------------------
  // Interface

  const COLUMN_HELP = {
    gender: "Green: same gender.",
    race: "Yellow: shares some races but not all, or a related race (Human / Modified Human, Giant / Ancient Giant, the sky-island peoples).",
    affiliation: "Main group. Yellow: your character's group is one the secret used to belong to, or one group names the other character (e.g. Whitebeard Pirates and Whitebeard).",
    status: "Alive, Deceased or Unknown.",
    fruit: "Devil Fruit type. Yellow: both have a fruit, of different types. Red: only one has a fruit.",
    haki: "Yellow: both use Haki, in a different combination. Red: only one uses Haki.",
    style: "Main way of fighting. Yellow: same family (blades, polearms, blunt weapons, ranged weapons like guns and bows, unarmed, gadgets). None = fights with a Devil Fruit or powers only.",
    bounty: "Latest bounty. The arrow points toward the secret's bounty.",
    height: "The arrow points toward the secret's height.",
    age: "Current age, or age at death. ~ means approximate.",
    debut: "Arc of the first manga appearance, or the cover story for characters introduced on a cover page (e.g. Garp: Diary of Koby-Meppo). Yellow: one of them debuted on a cover page during the same arc. ↑ the secret debuted later, ↓ earlier.",
    episode: "First anime episode.",
    origin: "Home region.",
  };
  const STATE_WORDS = { match: "correct", partial: "partial match", miss: "wrong", unknown: "no data" };
  // Small corner marks so the colors are not the only cue.
  const STATE_SYMBOLS = { match: "✓", partial: "≈", miss: "✕", unknown: "?" };
  // Cell reveal: each cell flips for FLIP_MS, starting FLIP_STAGGER_MS after the previous one.
  const FLIP_MS = 850;
  const FLIP_STAGGER_MS = 300;
  const ARROW_WORDS = { up: ", secret is higher", down: ", secret is lower" };

  function startInterface(doc) {
    const characters = global.CHARACTERS || [];
    const index = buildSearchIndex(characters);
    const byId = new Map(characters.map((c) => [c.id, c]));
    const $ = (id) => doc.getElementById(id);
    const input = $("guess-input");
    const list = $("suggestions");
    const board = $("board");
    const hintsEl = $("hints");
    const result = $("result");
    const statusLine = $("status-line");

    const round = { secret: null, guesses: [], over: false, won: false, revealed: new Set() };
    let suggestions = [];
    let active = -1;

    function el(tag, props = {}, ...children) {
      const node = doc.createElement(tag);
      for (const [key, value] of Object.entries(props)) {
        if (value === undefined || value === null || value === false) continue;
        if (key === "class") node.className = value;
        else if (key === "style") node.style.cssText = value;
        else if (key.startsWith("on")) node.addEventListener(key.slice(2), value);
        else node.setAttribute(key, value === true ? "" : value);
      }
      for (const child of children.flat()) {
        if (child !== null && child !== undefined && child !== false) {
          node.append(child.nodeType ? child : String(child));
        }
      }
      return node;
    }

    const badge = (c) => el("span", { class: "badge", style: `background:${badgeColor(c.name)}`, "aria-hidden": "true" }, initials(c.name));

    // --- Board

    board.style.setProperty("--flip-ms", FLIP_MS + "ms");
    board.style.setProperty("--flip-stagger", FLIP_STAGGER_MS + "ms");

    function renderHeader() {
      board.replaceChildren(el("div", { class: "row head", role: "row" },
        el("div", { class: "cell name", role: "columnheader" }, "Character"),
        COLUMNS.map((col) => el("div", { class: "cell", role: "columnheader", title: COLUMN_HELP[col.key] }, col.label))));
    }

    function addRow(guess, animate) {
      const results = compareCharacters(guess, round.secret);
      const row = el("div", { class: animate ? "row new" : "row", role: "row" },
        el("div", { class: "cell name", role: "cell" }, badge(guess), el("span", {}, guess.name)),
        results.map((r, i) => el("div", {
          class: `cell ${r.state}`, role: "cell", style: `--i:${i}`, "data-symbol": STATE_SYMBOLS[r.state],
          "aria-label": `${COLUMNS[i].label}: ${r.text}, ${STATE_WORDS[r.state]}${r.arrow ? ARROW_WORDS[r.arrow] : ""}`,
        }, el("span", {}, r.text), r.arrow ? el("span", { class: "arrow", "aria-hidden": "true" }, r.arrow === "up" ? "↑" : "↓") : null)));
      board.firstChild.after(row); // newest guess on top, under the header
    }

    // --- Hints and status

    function wrongGuesses() {
      return round.guesses.length - (round.won ? 1 : 0);
    }

    function renderHints() {
      const wrong = wrongGuesses();
      hintsEl.replaceChildren(...HINTS.map((hint) => {
        const left = hint.after - wrong;
        const unlocked = left <= 0 || round.over;
        const shown = round.over || round.revealed.has(hint.key);
        let value;
        if (!unlocked) value = el("span", { class: "value" }, `Unlocks in ${left} guess${left === 1 ? "" : "es"}`);
        else if (!shown) value = el("button", { type: "button", onclick: () => revealHint(hint.key) }, "Reveal");
        else value = el("span", { class: "value", tabindex: "-1" }, hint.text(round.secret));
        return el("div", { class: `hint panel${unlocked ? "" : " locked"}`, "data-key": hint.key },
          el("span", { class: "label" }, hint.label), value);
      }));
    }

    function revealHint(key) {
      round.revealed.add(key);
      renderHints();
      onChange();
      const value = hintsEl.querySelector(`[data-key="${key}"] .value`);
      if (value) value.focus(); // keep keyboard users in place
    }

    function renderStatus() {
      const n = round.guesses.length;
      statusLine.textContent = n ? `${n} guess${n === 1 ? "" : "es"}` : "Make your first guess.";
    }

    function renderRules() {
      const rules = $("rules-list");
      if (!rules) return;
      rules.replaceChildren(...COLUMNS.map((col) => el("li", {}, el("b", {}, col.label + ": "), COLUMN_HELP[col.key])));
    }

    function showResult() {
      if (!round.over) return; // a new round started before the delayed panel appeared
      const s = round.secret;
      const n = round.guesses.length;
      result.replaceChildren(
        badge(s),
        el("h2", {}, round.won ? `It was ${s.name}!` : `The answer was ${s.name}`),
        el("p", {}, round.won ? `Found in ${n} guess${n === 1 ? "" : "es"}.` : `You gave up after ${n} guess${n === 1 ? "" : "es"}.`),
        el("div", { class: "actions" },
          el("button", { class: "btn btn-primary", type: "button", onclick: () => api.nextRound() }, "Next character"),
          el("a", { class: "btn", href: wikiUrl(s), target: "_blank", rel: "noopener" }, "Read about them on the wiki")));
      result.hidden = false;
      result.querySelector("button").focus();
    }

    // --- Guessing

    function makeGuess(c) {
      if (round.over || round.guesses.some((g) => g.id === c.id)) return;
      round.guesses.push(c);
      addRow(c, true);
      if (c.id === round.secret.id) {
        round.won = true;
        const reducedMotion = global.matchMedia && global.matchMedia("(prefers-reduced-motion: reduce)").matches;
        // Let the last cell finish flipping before the win panel appears.
        endRound(reducedMotion ? 0 : (COLUMNS.length - 1) * FLIP_STAGGER_MS + FLIP_MS + 150);
      }
      renderHints();
      renderStatus();
      onChange();
      if (!round.over) input.focus();
    }

    let resultTimer = null;

    function endRound(delay = 0) {
      round.over = true;
      input.disabled = true;
      closeList();
      clearTimeout(resultTimer);
      resultTimer = setTimeout(showResult, delay);
      api.onRoundEnd(round);
    }

    // --- Suggestions (keyboard: ↑ ↓ Enter Esc)

    function closeList() {
      list.hidden = true;
      input.setAttribute("aria-expanded", "false");
      input.removeAttribute("aria-activedescendant");
    }

    function setActive(i) {
      active = i;
      [...list.children].forEach((li, j) => li.setAttribute("aria-selected", String(j === active)));
      if (active >= 0) {
        input.setAttribute("aria-activedescendant", `suggestion-${active}`);
        list.children[active].scrollIntoView({ block: "nearest" });
      }
    }

    function renderSuggestions() {
      const query = input.value.trim();
      if (!query) { suggestions = []; closeList(); return; }
      suggestions = searchCharacters(index, query, new Set(round.guesses.map((g) => g.id)));
      list.replaceChildren(...(suggestions.length
        ? suggestions.map((s, i) => el("li", {
          id: `suggestion-${i}`, role: "option", "aria-selected": "false",
          onmousedown: (event) => { event.preventDefault(); choose(i); },
        }, badge(s.c), el("span", {}, s.c.name, s.via ? el("span", { class: "via" }, ` · ${s.via}`) : null)))
        : [el("li", { class: "empty", role: "option", "aria-disabled": "true" }, "No character found")]));
      list.hidden = false;
      input.setAttribute("aria-expanded", "true");
      setActive(suggestions.length ? 0 : -1);
    }

    function choose(i) {
      const picked = suggestions[i];
      if (!picked) return;
      input.value = "";
      closeList();
      makeGuess(picked.c);
    }

    input.addEventListener("input", renderSuggestions);
    input.addEventListener("focus", () => { if (input.value.trim()) renderSuggestions(); });
    input.addEventListener("blur", () => setTimeout(closeList, 120));
    input.addEventListener("keydown", (event) => {
      if (event.key === "ArrowDown" && suggestions.length) { event.preventDefault(); setActive((active + 1) % suggestions.length); }
      else if (event.key === "ArrowUp" && suggestions.length) { event.preventDefault(); setActive((active - 1 + suggestions.length) % suggestions.length); }
      else if (event.key === "Enter") { event.preventDefault(); if (!list.hidden) choose(active); }
      else if (event.key === "Escape") closeList();
    });

    // --- Rounds

    /** Start a round, or restore a saved one ({guessIds, revealed, gaveUp}). */
    function startRound(secret, saved = {}) {
      clearTimeout(resultTimer);
      round.secret = secret;
      round.guesses = [];
      round.over = false;
      round.won = false;
      round.gaveUp = false;
      round.revealed = new Set(saved.revealed || []);
      result.hidden = true;
      input.disabled = false;
      input.value = "";
      closeList();
      renderHeader();
      for (const id of saved.guessIds || []) {
        const c = byId.get(id);
        if (!c) continue;
        round.guesses.push(c);
        addRow(c, false);
        if (c.id === secret.id) round.won = true;
      }
      round.gaveUp = !round.won && Boolean(saved.gaveUp);
      renderHints();
      renderStatus();
      if (round.won || round.gaveUp) {
        round.over = true;
        input.disabled = true;
        renderHints();
        showResult();
      } else {
        input.focus();
      }
      onChange();
    }

    function giveUp() {
      if (round.over) return;
      round.gaveUp = true;
      endRound(0);
      renderHints();
      onChange();
    }

    function onChange() {
      api.onChange(round);
    }

    renderRules();

    // Default round handling; the unlimited-mode section below replaces these hooks.
    const api = {
      round, characters, byId, el, startRound, giveUp,
      pickSecret: () => {
        const pool = characters.filter((c) => c.tier === 1 || c.tier === 2);
        return pool[Math.floor(Math.random() * pool.length)];
      },
      nextRound: () => startRound(api.pickSecret()),
      onChange: () => {},
      onRoundEnd: () => {},
    };
    return api;
  }

  // ---------------------------------------------------------------------------
  // Unlimited mode: tick which groups of characters can be the secret (Easy,
  // Medium, Hard, any mix), a shuffled deck per mix (no repeats until it runs
  // out), give up, stats, and the current round saved across reloads.

  const GROUPS = [
    { tier: 1, label: "Easy", help: "The best-known characters: the Straw Hats, Emperors, Admirals and other big names." },
    { tier: 2, label: "Medium", help: "Well-known characters from across the story." },
    { tier: 3, label: "Hard", help: "Everyone else with enough data to be guessable." },
  ];
  const DEFAULT_TIERS = [1, 2];
  const OLD_DIFFICULTY_TIERS = { easy: [1], normal: [1, 2], hard: [1, 2, 3] }; // saves from before the checkboxes
  const STORAGE = "opg.";

  /** The ticked tiers in a fixed order, or null if none are valid. */
  function cleanTiers(value) {
    const tiers = Array.isArray(value) ? GROUPS.map((g) => g.tier).filter((t) => value.includes(t)) : [];
    return tiers.length ? tiers : null;
  }

  // Browser storage can be missing or blocked (private windows). Values are also kept
  // in memory, so stats and the deck still work for the session when it is.
  const memory = new Map();
  const isObject = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
  const store = {
    /** The stored value, or `fallback` if missing, unreadable or not the fallback's shape. */
    get(key, fallback) {
      let value = memory.has(key) ? memory.get(key) : undefined;
      if (value === undefined) {
        try {
          const raw = global.localStorage.getItem(STORAGE + key);
          if (raw !== null) value = JSON.parse(raw);
        } catch (error) { /* blocked or corrupt */ }
      }
      if (value === undefined || value === null) return fallback;
      if (isObject(fallback) ? !isObject(value) : typeof value !== typeof fallback) return fallback;
      return value;
    },
    set(key, value) {
      memory.set(key, value);
      try { global.localStorage.setItem(STORAGE + key, JSON.stringify(value)); } catch (error) { /* ignore */ }
    },
  };

  function shuffle(items) {
    const out = items.slice();
    for (let i = out.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [out[i], out[j]] = [out[j], out[i]];
    }
    return out;
  }

  /** Ids of the characters that can be the secret for these tiers (tier 0 never is). */
  const poolFor = (characters, tiers) =>
    characters.filter((c) => c.tier >= 1 && tiers.includes(c.tier)).map((c) => c.id);

  /** Next secret id from the deck; reshuffles when empty, never repeating the last one. */
  function drawFromDeck(deck, pool, lastId) {
    const valid = new Set(pool);
    let remaining = (Array.isArray(deck) ? deck : []).filter((id) => valid.has(id));
    if (!remaining.length) {
      remaining = shuffle(pool);
      if (remaining.length > 1 && remaining[remaining.length - 1] === lastId) {
        [remaining[0], remaining[remaining.length - 1]] = [remaining[remaining.length - 1], remaining[0]];
      }
    }
    const id = remaining.pop();
    return { id, deck: remaining };
  }

  const EMPTY_STATS = { played: 0, won: 0, guessesInWins: 0, streak: 0, bestStreak: 0 };

  function recordResult(stats, won, guesses) {
    const next = { ...EMPTY_STATS, ...stats };
    next.played += 1;
    if (won) {
      next.won += 1;
      next.guessesInWins += guesses;
      next.streak += 1;
      next.bestStreak = Math.max(next.bestStreak, next.streak);
    } else {
      next.streak = 0;
    }
    return next;
  }

  function setupUnlimited(ui, doc) {
    const { el, round, characters, byId } = ui;
    const controls = doc.getElementById("controls");
    let tiers = cleanTiers(store.get("tiers", [])) || OLD_DIFFICULTY_TIERS[store.get("difficulty", "")] || DEFAULT_TIERS;
    const deckKey = () => "tiers" + tiers.join("");

    function saveRound() {
      if (!round.secret) return;
      store.set("round", {
        tiers: tiers.slice(),
        secretId: round.secret.id,
        guessIds: round.guesses.map((g) => g.id),
        revealed: [...round.revealed],
        gaveUp: Boolean(round.gaveUp),
      });
      giveUpButton.disabled = round.over;
    }

    let allowRepeats = store.get("repeats", false);

    ui.pickSecret = () => {
      const pool = poolFor(characters, tiers);
      if (allowRepeats) {
        // Any character from the pool, just not the one you were just playing.
        const choices = pool.length > 1 && round.secret ? pool.filter((id) => id !== round.secret.id) : pool;
        return byId.get(choices[Math.floor(Math.random() * choices.length)]);
      }
      const decks = store.get("decks", {});
      const { id, deck } = drawFromDeck(decks[deckKey()], pool, round.secret && round.secret.id);
      decks[deckKey()] = deck;
      store.set("decks", decks);
      return byId.get(id);
    };
    ui.nextRound = () => {
      poolNote.textContent = "";
      ui.startRound(ui.pickSecret());
    };
    ui.onChange = saveRound;
    ui.onRoundEnd = () => {
      store.set("stats", recordResult(store.get("stats", EMPTY_STATS), round.won, round.guesses.length));
    };

    // --- Controls: character groups, repeats, give up, stats
    const poolNote = el("span", { class: "pool-note", role: "status" });
    const groupBoxes = GROUPS.map((g) => {
      const box = el("input", { type: "checkbox", id: `group-${g.tier}` });
      box.checked = tiers.includes(g.tier);
      box.addEventListener("change", () => onGroupsChange(box));
      return box;
    });
    const groups = el("div", { class: "groups", role: "group", "aria-label": "Characters that can be the secret" },
      el("span", { class: "groups-label" }, "Characters:"),
      GROUPS.map((g, i) => el("label", { class: "toggle", for: `group-${g.tier}`, title: g.help },
        groupBoxes[i], `${g.label} (${poolFor(characters, [g.tier]).length})`)));

    function onGroupsChange(changed) {
      const picked = GROUPS.filter((g, i) => groupBoxes[i].checked).map((g) => g.tier);
      if (!picked.length) {
        changed.checked = true;
        poolNote.textContent = "Keep at least one group ticked.";
        return;
      }
      tiers = picked;
      store.set("tiers", tiers);
      if (!round.over && !round.guesses.length) {
        ui.nextRound(); // nothing played yet: switch to the new pool right away
        changed.focus();
      } else {
        poolNote.textContent = "The new mix applies from the next character.";
      }
    }

    const giveUpButton = el("button", { class: "btn", type: "button", onclick: () => ui.giveUp() }, "Give up");
    const statsButton = el("button", { class: "btn", type: "button", onclick: openStats }, "Stats");
    // Off: no character repeats until the whole pool has been played. Applies from the next round.
    const repeatsBox = el("input", { type: "checkbox", id: "allow-repeats" });
    repeatsBox.checked = allowRepeats;
    repeatsBox.addEventListener("change", () => {
      allowRepeats = repeatsBox.checked;
      store.set("repeats", allowRepeats);
    });
    const repeatsToggle = el("label", { class: "toggle", for: "allow-repeats",
      title: "When off, you won't see a character again until you've played everyone in the ticked groups. Takes effect from the next round." },
    repeatsBox, "Allow repeats");
    controls.replaceChildren(groups, repeatsToggle, giveUpButton, statsButton, poolNote);

    // --- Stats dialog
    const dialog = el("dialog", { "aria-labelledby": "stats-title" });
    doc.body.append(dialog);

    function openStats() {
      const s = { ...EMPTY_STATS, ...store.get("stats", EMPTY_STATS) };
      const average = s.won ? (s.guessesInWins / s.won).toFixed(1) : "–";
      const winRate = s.played ? Math.round((100 * s.won) / s.played) + "%" : "–";
      const tile = (value, label) => el("div", {}, el("b", {}, String(value)), el("span", {}, label));
      dialog.replaceChildren(
        el("h2", { id: "stats-title" }, "Your stats"),
        el("div", { class: "stats" },
          tile(s.played, "Rounds played"), tile(winRate, "Solved"),
          tile(average, "Average guesses"), tile(s.won, "Characters found"),
          tile(s.streak, "Current streak"), tile(s.bestStreak, "Best streak")),
        el("div", { class: "actions", style: "display:flex;gap:8px;justify-content:flex-end" },
          el("button", { class: "btn", type: "button", onclick: resetStats }, "Reset stats"),
          el("button", { class: "btn btn-primary", type: "button", onclick: () => dialog.close() }, "Close")));
      if (dialog.showModal) dialog.showModal(); else dialog.setAttribute("open", "");
      dialog.querySelector(".btn-primary").focus(); // start on Close, not Reset
    }

    function resetStats() {
      if (global.confirm && !global.confirm("Reset all your stats?")) return;
      store.set("stats", EMPTY_STATS);
      openStats();
    }

    // --- Restore the saved round, or start a new one
    const saved = store.get("round", {});
    const savedSecret = byId.get(saved.secretId);
    if (savedSecret && tiers.includes(savedSecret.tier)) {
      ui.startRound(savedSecret, {
        guessIds: Array.isArray(saved.guessIds) ? saved.guessIds : [],
        revealed: Array.isArray(saved.revealed) ? saved.revealed : [],
        gaveUp: saved.gaveUp === true,
      });
    } else {
      ui.nextRound();
    }
  }

  global.OPG.unlimited = { drawFromDeck, recordResult, poolFor, cleanTiers, GROUPS };

  if (global.document) {
    const boot = () => {
      const ui = startInterface(global.document);
      setupUnlimited(ui, global.document);
      global.OPG.ui = ui;
    };
    if (global.document.readyState === "loading") global.document.addEventListener("DOMContentLoaded", boot);
    else boot();
  }
})(typeof window !== "undefined" ? window : globalThis);
